// Server-only: topic summaries for the public /topics pages, generated by
// scripts/build-card-index.mjs (copied to web/data/topics.json) from the
// disclosed card archive. Read at build time; the pages are static.
import fs from 'node:fs'
import path from 'node:path'

export type TopicSideSummary = {
  cards: number
  docs: number
  arguments: { label: string; docs: number }[]
  themes: { label: string; docs: number }[]
  authors: { label: string; docs: number }[]
  examples: { id: string; tag: string; cite: string; argument: string }[]
}

export type TopicSummary = {
  season: string
  cycle: string
  resolution: string
  docs: number
  teams: number
  cards: number
  sides: { Pro: TopicSideSummary; Con: TopicSideSummary }
}

export type Topic = TopicSummary & { slug: string; label: string; year: number; sortKey: number }

const CYCLE_ORDER = ['september-october', 'november-december', 'january', 'february', 'march', 'april', 'nationals']
const CYCLE_NAMES: Record<string, string> = {
  'september-october': 'September–October',
  'november-december': 'November–December',
  january: 'January',
  february: 'February',
  march: 'March',
  april: 'April',
  nationals: 'Nationals',
}

function topicYear(season: string, cycle: string): number {
  const start = Number(season.slice(0, 4))
  return cycle === 'september-october' || cycle === 'november-december' ? start : start + 1
}

function readSummaries(): TopicSummary[] {
  // Written by scripts/build-card-index.mjs into web/data/ (gitignored).
  // Only read during `next build` (cwd = web/): the pages are static.
  try {
    return JSON.parse(fs.readFileSync(path.join(process.cwd(), 'data', 'topics.json'), 'utf8')).topics as TopicSummary[]
  } catch {
    return []
  }
}

let cache: Topic[] | null = null

/** All topics with a public page, newest first. */
export function getTopics(): Topic[] {
  if (cache) return cache
  cache = readSummaries()
    .filter((t) => CYCLE_NAMES[t.cycle])
    .map((t) => {
      const year = topicYear(t.season, t.cycle)
      return {
        ...t,
        year,
        label: `${CYCLE_NAMES[t.cycle]} ${year}`,
        slug: `pf-${t.cycle}-${year}`,
        sortKey: Number(t.season.slice(0, 4)) * 10 + CYCLE_ORDER.indexOf(t.cycle),
      }
    })
    .sort((a, b) => b.sortKey - a.sortKey)
  return cache
}

export function getTopic(slug: string): Topic | undefined {
  return getTopics().find((t) => t.slug === slug)
}
